use hs_loop::*;use serde_json::{json,Value};
fn rig()->(tempfile::TempDir,InnerLoop){let d=tempfile::tempdir().unwrap();let cfg=d.path().join("rig");std::fs::write(&cfg,format!("[[models]]\nname='seqmodel'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-seqmodel"))).unwrap();let mut lp=InnerLoop::new(hs_kernel::Kernel::load(&cfg).unwrap(),d.path(),false,4).unwrap();lp.set_answer_root(Some(d.path().to_path_buf()));(d,lp)}
fn skill(root:&std::path::Path,path:&str,text:&str){let p=root.join(path);std::fs::create_dir_all(p.parent().unwrap()).unwrap();std::fs::write(p,text).unwrap();}
#[test]fn filesystem_skill_loads_full_yaml_body_and_resource_base(){let(d,mut lp)=rig();skill(d.path(),".dsh/skills/parser/SKILL.md","---\nname: parser\ndescription: |\n  Repair the parser.\n---\n# Parser\nUse fixtures.\n");let out=lp.dispatch_tool_for_test("skill",&json!({"name":"parser"})).unwrap();assert_eq!(out.output["name"],"parser");assert_eq!(out.output["provider"],"filesystem");assert_eq!(out.output["content"],"# Parser\nUse fixtures.");assert_eq!(out.output["resourceBase"]["path"],d.path().join(".dsh/skills/parser").to_str().unwrap());assert_ne!(out.start_event_id,uuid::Uuid::nil());}
#[test]fn lower_rank_wins_and_disabled_winner_does_not_fallback(){let(d,mut lp)=rig();skill(d.path(),".dsh/skills/a.md","---\nname: alpha\ndescription: Primary\ndisable-model-invocation: true\n---\nHidden");skill(d.path(),".agents/skills/a.md","---\nname: alpha\ndescription: Fallback\n---\nWrong fallback");let out=lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap();assert!(out.output["error"].as_str().unwrap().contains("not available for model invocation"));}
#[test]fn unknown_and_path_traversal_fail_without_reading_arbitrary_file(){let(d,mut lp)=rig();skill(d.path(),"secret","SECRET");for name in ["missing","../secret","Bad_Name","","a/b"]{let out=lp.dispatch_tool_for_test("skill",&json!({"name":name})).unwrap();assert!(out.output["error"].is_string());assert!(!out.output.to_string().contains("SECRET"));}}
#[test]fn mutation_is_seen_and_invalid_metadata_not_loaded(){let(d,mut lp)=rig();let p=".dsh/skills/a.md";skill(d.path(),p,"---\nname: alpha\ndescription: A\n---\nfirst");assert_eq!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["content"],"first");skill(d.path(),p,"---\nname: alpha\ndescription: A\n---\nsecond");assert_eq!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["content"],"second");skill(d.path(),p,"---\nname: alpha\ndescription: A\nmodelInvocable: true\n---\nlegacy");assert!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["error"].is_string());}
#[test]fn loaded_skill_history_is_canonical_not_struct_dump(){let d=tempfile::tempdir().unwrap();let id=uuid::Uuid::new_v4();let mut w=hs_log::StreamWriter::create(d.path(),id).unwrap();let v=json!({"name":"alpha","provider":"filesystem","resourceBase":{"kind":"directory","path":"/tmp/a&b"},"content":"# Instructions\nUse data."});w.append(hs_core::EventBuilder::new(hs_core::EventKind::ToolCall).payload(hs_core::Payload::Inline(serde_json::to_vec(&json!({"plugin":"skill","args":{"name":"alpha"},"result":v})).unwrap()))).unwrap();let r=hs_log::StreamReader::open(d.path(),id).unwrap();let a=assembler::assemble_messages(&r,&r.events().unwrap(),20000);assert_eq!(a.messages[1]["content"],hs_loop::dshskill::render(&v));}
#[test]fn custom_roots_precedence_and_catalog_visibility_are_scope_owned(){let d=tempfile::tempdir().unwrap();skill(d.path(),"custom/a.md","---\nname: alpha\ndescription: Description\n---\nInstructions");let roots=vec![dshskill::SkillRoot{path:d.path().join("custom"),rank:300,skip_system:false}];let catalog=dshskill::catalog(&roots).unwrap();assert_eq!(catalog,json!([{"name":"alpha","description":"Description"}]));assert_eq!(dshskill::call(&roots,&json!({"name":"alpha"})).unwrap()["content"],"Instructions");}
#[test]fn loaded_skill_over_20kb_is_not_silently_truncated(){let d=tempfile::tempdir().unwrap();let id=uuid::Uuid::new_v4();let mut w=hs_log::StreamWriter::create(d.path(),id).unwrap();let body="x".repeat(25000);let v=json!({"name":"alpha","provider":"filesystem","resourceBase":{"kind":"directory","path":"/tmp/alpha"},"content":body});w.append(hs_core::EventBuilder::new(hs_core::EventKind::ToolCall).payload(hs_core::Payload::Inline(serde_json::to_vec(&json!({"plugin":"skill","args":{"name":"alpha"},"result":v})).unwrap()))).unwrap();let r=hs_log::StreamReader::open(d.path(),id).unwrap();let a=assembler::assemble_messages(&r,&r.events().unwrap(),100000);assert_eq!(a.messages[1]["content"],dshskill::render(&v));}
#[test]fn file_disappearance_and_yaml_errors_are_unknown_not_stale(){let(d,mut lp)=rig();let p=".dsh/skills/a.md";skill(d.path(),p,"---\nname: alpha\ndescription: A\n---\nfirst");lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap();std::fs::remove_file(d.path().join(p)).unwrap();assert!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["error"].is_string());skill(d.path(),p,"---\nname: [bad\n---\nshould not load");assert!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["error"].is_string());}
#[test]fn skill_catalog_is_durable_and_in_actual_model_request(){let(d,mut lp)=rig();skill(d.path(),".dsh/skills/a.md","---\nname: alpha\ndescription: Task instructions\n---\nBody");lp.run_mission("catalog-fixture").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let v:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();assert_eq!(v.iter().filter(|v|v["record_type"]=="skill/catalog").count(),1);assert!(v.iter().filter_map(|v|v["messages"].as_array()).any(|m|m.iter().any(|m|m["content"].as_str().is_some_and(|s|s.contains("- `alpha`: Task instructions")))));}
#[test]fn repeated_catalog_keeps_the_initial_model_prefix_exact(){let(d,mut lp)=rig();skill(d.path(),".dsh/skills/a.md","---\nname: alpha\ndescription: A\n---\nBody");lp.run_mission("prefix").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let v:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();let catalogs:Vec<String>=v.iter().filter_map(|v|v["messages"].as_array()).flat_map(|m|m.iter()).filter_map(|m|m["content"].as_str()).filter(|s|s.contains("<available_skills>")).map(str::to_owned).collect();assert!(catalogs.len()>1);assert!(catalogs.windows(2).all(|p|p[0]==p[1]));}
#[test]fn configured_roots_omit_system_and_project_when_defaults_off(){let d=tempfile::tempdir().unwrap();let home=d.path().join("home");skill(&home,"skills/.system/SKILL.md","---\nname: hidden\ndescription: H\n---\nHidden");skill(&home,"skills/alpha.md","---\nname: alpha\ndescription: A\n---\nBody");let c=dshskill::RootConfig{dsh_home:Some(home),agents_home:Some(d.path().join("empty")),..Default::default()};assert_eq!(dshskill::catalog(&c.roots(None)).unwrap(),json!([{"name":"alpha","description":"A"}]));let off=dshskill::RootConfig{include_default_roots:false,..c};assert!(off.roots(Some(d.path())).is_empty());}
#[test]fn catalog_description_caps_utf16_units_like_source(){let d=tempfile::tempdir().unwrap();let description="😀".repeat(300);skill(d.path(),"a.md",&format!("---\nname: alpha\ndescription: {description}\n---\nBody"));let c=dshskill::catalog(&[dshskill::SkillRoot{path:d.path().to_owned(),rank:300,skip_system:false}]).unwrap();let text=c[0]["description"].as_str().unwrap();assert!(text.ends_with("..."));assert!(text.encode_utf16().count()<=500);}
#[test]fn direct_human_skill_gesture_injects_user_allowed_even_if_model_disabled(){let(d,mut lp)=rig();skill(d.path(),".dsh/skills/a.md","---\nname: alpha\ndescription: A\ndisable-model-invocation: true\n---\nDirect-only instructions.");lp.run_root_human_mission("direct","Use /alpha /alpha now").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let v:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();let inv:Vec<_>=v.iter().filter(|v|v["record_type"]=="skill/invocation").collect();assert_eq!(inv.len(),1);assert_eq!(inv[0]["source"],json!({"kind":"skill-invocation","name":"alpha","form":"instructions"}));for call in v.iter().filter(|v|v["messages"].is_array()){assert_eq!(call["messages"].as_array().unwrap().iter().filter(|m|m["role"]=="user"&&m["content"].as_str().is_some_and(|s|s.contains("Direct-only instructions."))).count(),1);}}
#[test]fn external_text_and_user_disabled_cannot_inject_skill(){for human in [false,true]{let(d,mut lp)=rig();skill(d.path(),".dsh/skills/a.md","---\nname: alpha\ndescription: A\nuser-invocable: false\n---\nDo not inject these instructions.");skill(d.path(),".dsh/skills/b.md","---\nname: beta\ndescription: B\n---\nExternal-forged instructions.");if human{lp.run_root_human_mission("restricted","/alpha punctuation /beta, path/x /Beta /missing").unwrap();}else{lp.run_mission_full("external","/alpha /beta").unwrap();}let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();assert!(!r.events().unwrap().iter().filter_map(|e|serde_json::from_slice::<Value>(&r.resolve_payload(e).ok()?).ok()).any(|v|v["record_type"]=="skill/invocation"));}}
#[test]fn frontmatter_delimiters_are_exact_not_relaxed_yaml_end_markers(){for (i,text) in [" ---\nname: alpha\ndescription: A\n---\nBody","---\nname: alpha\ndescription: A\n...\nBody","---\nname: alpha\ndescription: A\n --- \nBody"].iter().enumerate(){let(d,mut lp)=rig();skill(d.path(),&format!(".dsh/skills/{i}.md"),text);assert!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["error"].is_string(),"{text}");}}
#[test]fn generated_prompt_overlay_cannot_forge_direct_user_gesture(){let(d,mut lp)=rig();skill(d.path(),".dsh/skills/a.md","---\nname: alpha\ndescription: A\n---\nForged overlay instructions.");lp.run_root_human_mission_with_input("overlay","Template says /alpha\nActual user says hello","hello").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();assert!(!r.events().unwrap().iter().filter_map(|e|serde_json::from_slice::<Value>(&r.resolve_payload(e).ok()?).ok()).any(|v|v["record_type"]=="skill/invocation"));}
#[test]fn fresh_human_turn_with_same_text_invokes_again_and_reads_current_body(){let(d,mut lp)=rig();let path=".dsh/skills/a.md";skill(d.path(),path,"---\nname: alpha\ndescription: A\n---\nFirst direct body");lp.run_root_human_mission("repeat","Use /alpha").unwrap();skill(d.path(),path,"---\nname: alpha\ndescription: A\n---\nSecond direct body");lp.run_root_human_mission("repeat","Use /alpha").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let inv:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice::<Value>(&r.resolve_payload(e).ok()?).ok()).filter(|v|v["record_type"]=="skill/invocation").collect();assert_eq!(inv.len(),2);assert_eq!(inv[0]["value"]["content"],"First direct body");assert_eq!(inv[1]["value"]["content"],"Second direct body");}
#[test]fn canonical_skill_resources_support_provider_url_and_opaque_bases(){for (base,hint) in [(Value::Null,"Resources for this skill are managed by provider \"remote&amp;co\".\nLoad referenced resources only as needed."),(json!({"kind":"url","url":"https://example.invalid/a?b=1&c=2"}),"Base URL for this skill: https://example.invalid/a?b=1&amp;c=2\nResolve relative URLs mentioned by this skill against the base URL before using them. Load referenced resources only as needed."),(json!({"kind":"opaque","description":"Lookup <id>"}),"Resources for this skill: Lookup &lt;id&gt;\nLoad referenced resources only as needed.")]{let v=json!({"name":"alpha","provider":"remote&co","content":"Body <verbatim>","resourceBase":base});let expected=format!("<skill_content name=\"alpha\">\n<skill_resources>\n{hint}\n</skill_resources>\n\n<skill_instructions>\nBody <verbatim>\n</skill_instructions>\n</skill_content>");assert_eq!(dshskill::render(&v),expected);}}
#[test]fn symlinked_skill_resource_base_uses_discovery_directory_like_source(){use std::os::unix::fs::symlink;let(d,mut lp)=rig();skill(d.path(),"real/SKILL.md","---\nname: alpha\ndescription: A\n---\nBody");std::fs::create_dir_all(d.path().join(".dsh/skills")).unwrap();symlink(d.path().join("real"),d.path().join(".dsh/skills/linked")).unwrap();assert_eq!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["resourceBase"]["path"],d.path().join(".dsh/skills/linked").to_str().unwrap());}
#[test]fn runtime_registration_has_defaults_rank_first_wins_and_session_ownership(){let(d,mut lp)=rig();let def=|body:&str|serde_json::from_value::<dshskill::RuntimeSkill>(json!({"name":"alpha","description":"Runtime summary","source":"test-host","content":body})).unwrap();assert!(lp.register_runtime_skill(def("Runtime body")).unwrap());assert!(!lp.register_runtime_skill(def("Wrong duplicate")).unwrap());assert_eq!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["content"],"Runtime body");skill(d.path(),".dsh/skills/a.md","---\nname: alpha\ndescription: Project\n---\nProject body");assert_eq!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["content"],"Project body");std::fs::remove_file(d.path().join(".dsh/skills/a.md")).unwrap();assert!(lp.remove_runtime_skill("alpha"));assert!(!lp.remove_runtime_skill("alpha"));assert!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["error"].is_string());let(_,mut other)=rig();assert!(other.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["error"].is_string());}
#[test]fn runtime_model_disabled_winner_cannot_fallback_to_user_root(){let(d,mut lp)=rig();skill(d.path(),"custom/a.md","---\nname: alpha\ndescription: User\n---\nWrong fallback");lp.set_skill_config(dshskill::RootConfig{include_default_roots:false,custom_skill_dirs:vec![d.path().join("custom")],..Default::default()});let def=serde_json::from_value(json!({"name":"alpha","description":"Runtime","source":"host","content":"Direct runtime","invocation":{"modelInvocable":false,"userInvocable":true},"resourceBase":{"kind":"url","url":"https://example.invalid/base"}})).unwrap();lp.register_runtime_skill(def).unwrap();assert!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["error"].as_str().unwrap().contains("not available for model invocation"));assert_eq!(lp.user_skill_names().unwrap(),vec!["alpha"]);lp.run_root_human_mission("runtime","Use /alpha").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let vals:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();assert!(vals.iter().any(|v|v["record_type"]=="skill/invocation"&&v["value"]["content"]=="Direct runtime"));assert!(vals.iter().filter_map(|v|v["messages"].as_array()).any(|m|m.iter().any(|v|v["content"].as_str().is_some_and(|s|s.contains("Base URL for this skill: https://example.invalid/base")))));}
#[test]fn malformed_runtime_names_and_descriptions_are_rejected_without_poisoning_registry(){let(_,mut lp)=rig();for (name,desc) in [("Bad_Name","A"),("alpha","")]{let skill=serde_json::from_value(json!({"name":name,"description":desc,"source":"host","content":"Body"})).unwrap();assert!(lp.register_runtime_skill(skill).is_err());}assert!(lp.user_skill_names().unwrap().is_empty());}
#[test]fn runtime_visible_catalog_uses_registered_description(){let(d,mut lp)=rig();let skill=serde_json::from_value(json!({"name":"alpha","description":"Runtime catalog","source":"host","provider":"embedded","content":"Runtime instructions"})).unwrap();lp.register_runtime_skill(skill).unwrap();let out=lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap();assert!(dshskill::render(&out.output).contains("Resources for this skill are managed by provider \"embedded\"."));lp.run_mission("catalog-runtime").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let vals:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();assert!(vals.iter().any(|v|v["record_type"]=="skill/catalog"&&v["entries"]==json!([{"name":"alpha","description":"Runtime catalog"}])));}
#[test]fn scoped_runtime_nearest_layer_wins_over_project_rank_and_teardown_reveals_parent(){let d=tempfile::tempdir().unwrap();skill(d.path(),"a.md","---\nname: alpha\ndescription: Project\n---\nProject body");let roots=vec![dshskill::SkillRoot{path:d.path().to_owned(),rank:100,skip_system:false}];let mut reg=dshskill::Registry::default();let def=|body:&str|serde_json::from_value(json!({"name":"alpha","description":"Runtime","source":"host","content":body})).unwrap();assert!(reg.register_scoped("parent",def("Parent body")).unwrap());assert!(reg.register_scoped("child",def("Child body")).unwrap());assert!(!reg.register_scoped("child",def("Duplicate body")).unwrap());let args=json!({"name":"alpha"});assert_eq!(reg.call_scoped(&roots,&[],&args).unwrap()["content"],"Project body");assert_eq!(reg.call_scoped(&roots,&["parent".into()],&args).unwrap()["content"],"Parent body");assert_eq!(reg.call_scoped(&roots,&["parent".into(),"child".into()],&args).unwrap()["content"],"Child body");assert!(reg.remove_scope("child"));assert!(!reg.remove_scope("child"));assert_eq!(reg.call_scoped(&roots,&["parent".into(),"child".into()],&args).unwrap()["content"],"Parent body");assert_eq!(reg.call_scoped(&roots,&["unrelated".into()],&args).unwrap()["content"],"Project body");}
#[test]fn scoped_disabled_winner_masks_global_project_for_catalog_and_model_but_not_user(){let(d,mut lp)=rig();skill(d.path(),".dsh/skills/a.md","---\nname: alpha\ndescription: Project\n---\nGlobal project");let def=serde_json::from_value(json!({"name":"alpha","description":"Scoped","source":"host","content":"Scoped user body","invocation":{"modelInvocable":false,"userInvocable":true}})).unwrap();lp.register_scoped_runtime_skill("near",def).unwrap();lp.set_skill_scope_chain(vec!["near".into()]);assert!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["error"].as_str().unwrap().contains("not available for model invocation"));lp.run_root_human_mission("scoped","Use /alpha").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let vals:Vec<Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();assert!(vals.iter().any(|v|v["record_type"]=="skill/invocation"&&v["value"]["content"]=="Scoped user body"));assert!(!vals.iter().filter(|v|v["record_type"]=="skill/catalog").any(|v|v["entries"].as_array().unwrap().iter().any(|e|e["name"]=="alpha")));lp.set_skill_scope_chain(vec![]);assert_eq!(lp.dispatch_tool_for_test("skill",&json!({"name":"alpha"})).unwrap().output["content"],"Global project");}
#[test]fn malformed_scope_registration_does_not_hide_valid_global_skill(){let mut reg=dshskill::Registry::default();let bad=serde_json::from_value(json!({"name":"Bad","description":"A","source":"host","content":"Wrong"})).unwrap();assert!(reg.register_scoped("near",bad).is_err());let good=serde_json::from_value(json!({"name":"alpha","description":"A","source":"host","content":"Global"})).unwrap();assert!(reg.register(good).unwrap());assert_eq!(reg.call_scoped(&[],&["near".into()],&json!({"name":"alpha"})).unwrap()["content"],"Global");assert!(reg.register_scoped("",serde_json::from_value(json!({"name":"beta","description":"B","source":"host","content":"Body"})).unwrap()).is_err());}
